const n = b.c.length;
const num = function (x, d) { const y = Number(x); return isFinite(y) ? y : d; };
const fastLen = Math.max(1, Math.round(num(p && p.fast, 9)));
const slowLen = Math.max(1, Math.round(num(p && p.slow, 200)));
const useEma = num(p && p.use_ema, 0) !== 0;
const reset = num(p && p.session_reset, 1) !== 0;
const day = b.day || null;
const vw = new Array(n).fill(null);
const buy = new Array(n).fill(null);
const sell = new Array(n).fill(null);

// forward-filled clean close series, so one bad bar cannot poison a rolling sum
const cc = new Array(n).fill(null);
let last = null, start = -1;
for (let i = 0; i < n; i++) {
  const c = num(b.c[i], NaN);
  if (isFinite(c)) { last = c; if (start < 0) start = i; }
  cc[i] = last;
}

const movavg = function (len) {
  const out = new Array(n).fill(null);
  if (start < 0) return out;
  if (useEma) {
    const k = 2 / (len + 1);
    let sum = 0, prev = null;
    for (let i = start; i < n; i++) {
      if (prev === null) {
        sum += cc[i];
        if (i - start === len - 1) { prev = sum / len; out[i] = prev; }
      } else {
        prev = cc[i] * k + prev * (1 - k);
        out[i] = prev;
      }
    }
  } else {
    let sum = 0;
    for (let i = start; i < n; i++) {
      sum += cc[i];
      if (i - start >= len) sum -= cc[i - len];
      if (i - start >= len - 1) out[i] = sum / len;
    }
  }
  return out;
};

const maF = movavg(fastLen);
const maS = movavg(slowLen);

// session-anchored VWAP
let pv = 0, vv = 0;
for (let i = 0; i < n; i++) {
  const hi = num(b.h[i], NaN), lo = num(b.l[i], NaN), cl = num(b.c[i], NaN);
  const vol = Math.max(0, num(b.v ? b.v[i] : 0, 0));
  if (reset && day && i > 0 && day[i] !== day[i - 1]) { pv = 0; vv = 0; }
  if (isFinite(hi) && isFinite(lo) && isFinite(cl)) {
    const tp = (hi + lo + cl) / 3;
    pv += tp * vol;
    vv += vol;
  }
  if (vv > 0) vw[i] = pv / vv;
}

// cross of fast over slow arms the side; it fires on the first bar price is
// clear of BOTH averages, then disarms until the next cross
let pending = 0;
for (let i = 1; i < n; i++) {
  const a = maF[i], z = maS[i], pa = maF[i - 1], pz = maS[i - 1];
  if (a === null || z === null || pa === null || pz === null) continue;
  if (a > z && pa <= pz) pending = 1;
  else if (a < z && pa >= pz) pending = -1;
  const cl = cc[i];
  if (cl === null) continue;
  if (pending === 1 && a > z && cl > a && cl > z) {
    const lo = num(b.l[i], NaN);
    buy[i] = isFinite(lo) ? lo : cl;
    pending = 0;
  } else if (pending === -1 && a < z && cl < a && cl < z) {
    const hi = num(b.h[i], NaN);
    sell[i] = isFinite(hi) ? hi : cl;
    pending = 0;
  }
}

return { VWAP: vw, MA_FAST: maF, MA_SLOW: maS, BUY: buy, SELL: sell };
